def transform(grid):
    out = [row[:] for row in grid]
    baseline = next((r for r, row in enumerate(grid) if any(row)), None)
    if baseline is None:
        return out
    heights = {2: 4, 8: 3}
    for col, value in enumerate(grid[baseline]):
        if value not in heights:
            continue
        top = max(0, baseline - heights[value])
        out[top][col] = value
        for r in range(top + 1, baseline):
            out[r][col] = 1
    return out
